func setupCasePageTestDB(t *testing.T) *gorm.DB {
	t.Helper()
	db, err := gorm.Open(mysql.Open("root:root@tcp(127.0.0.1:3307)/aegis_test?charset=utf8mb4&parseTime=True&loc=Local"), &gorm.Config{})
	if err != nil {
		t.Fatalf("open mysql: %v", err)
	}
	if err := db.AutoMigrate(&model.FunctionalCase{}); err != nil {
		t.Fatalf("automigrate functional_case: %v", err)
	}
	config.DB = db
	return db
}

func TestGetCasePage_EmptyProject_ListMustBeEmptyArray(t *testing.T) {
	db := setupCasePageTestDB(t)
	if err := db.Exec("DELETE FROM functional_case WHERE project_id = ?", "p-empty").Error; err != nil {
		t.Fatalf("clean fixture: %v", err)
	}

	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.POST("/functional/case/page", NewTestCaseHandler().GetCasePage)

	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodPost, "/functional/case/page", bytes.NewReader([]byte(`{"projectId":"p-empty","current":1,"pageSize":10}`)))
	req.Header.Set("Content-Type", "application/json")
	r.ServeHTTP(w, req)

	var envelope struct {
		Code    int             `json:"code"`
		Data    json.RawMessage `json:"data"`
		Message string          `json:"message"`
	}
	if err := json.Unmarshal(w.Body.Bytes(), &envelope); err != nil {
		t.Fatalf("envelope unmarshal: %v body=%s", err, w.Body.String())
	}
	if w.Code != http.StatusOK || envelope.Code != 200 {
		t.Fatalf("http=%d code=%d message=%s", w.Code, envelope.Code, envelope.Message)
	}

	var page struct {
		List       json.RawMessage `json:"list"`
		Total      int64           `json:"total"`
		Current    *int            `json:"current"`
		PageSize   *int            `json:"pageSize"`
		TotalPages int64           `json:"totalPages"`
	}
	if err := json.Unmarshal(envelope.Data, &page); err != nil {
		t.Fatalf("page unmarshal: %v data=%s", err, string(envelope.Data))
	}
	if got := string(bytes.TrimSpace(page.List)); got != "[]" {
		t.Errorf("契约破坏: data.list=%s, want [] (var list []model.FunctionalCase 为 nil 时序列化成 null)", got)
	}
	if page.Total != 0 || page.TotalPages != 0 {
		t.Errorf("空结果分页元数据错误: total=%d totalPages=%d, want 0/0", page.Total, page.TotalPages)
	}
	if page.Current == nil || *page.Current != 1 {
		t.Errorf("分页元数据缺失: current=%v, want 1 (PageResult.Current 带 omitempty, 0 值被省略)", page.Current)
	}
	if page.PageSize == nil || *page.PageSize != 10 {
		t.Errorf("分页元数据缺失: pageSize=%v, want 10", page.PageSize)
	}
}

