func TestGetCasePage_MissingPagingParams_MustEchoEffectiveMeta(t *testing.T) {
	db := setupCasePageMetaTestDB(t)
	if err := db.Exec("DELETE FROM functional_case WHERE project_id = ?", "p-meta").Error; err != nil {
		t.Fatalf("clean fixture: %v", err)
	}
	for i := 0; i < 11; i++ {
		row := model.FunctionalCase{
			ID:        "page-meta-" + string(rune('a'+i)),
			ProjectID: "p-meta",
			ModuleID:  "mod-1",
			Name:      "分页用例",
			Deleted:   model.BitBool(false),
			CreatedAt: int64(1000 + i),
			UpdatedAt: int64(1000 + i),
		}
		if err := db.Create(&row).Error; err != nil {
			t.Fatalf("seed %d: %v", i, err)
		}
	}

	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.POST("/functional/case/page", NewTestCaseHandler().GetCasePage)

	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodPost, "/functional/case/page", bytes.NewReader([]byte(`{"projectId":"p-meta","keyword":"分页"}`)))
	req.Header.Set("Content-Type", "application/json")
	r.ServeHTTP(w, req)

	var envelope struct {
		Code int             `json:"code"`
		Data json.RawMessage `json:"data"`
	}
	if err := json.Unmarshal(w.Body.Bytes(), &envelope); err != nil {
		t.Fatalf("envelope unmarshal: %v body=%s", err, w.Body.String())
	}
	var page struct {
		Total      int64 `json:"total"`
		TotalPages int64 `json:"totalPages"`
		Current    *int  `json:"current"`
		PageSize   *int  `json:"pageSize"`
	}
	if err := json.Unmarshal(envelope.Data, &page); err != nil {
		t.Fatalf("page unmarshal: %v data=%s", err, string(envelope.Data))
	}
	if page.Current == nil {
		t.Errorf("响应缺少 current 字段: GetCasePage 值传递, service 兜底后的 1/10 没有回写到 handler 的 params")
	} else if *page.Current != 1 {
		t.Errorf("current=%d, want 1", *page.Current)
	}
	if page.PageSize == nil {
		t.Errorf("响应缺少 pageSize 字段: response.PageResult.PageSize 带 omitempty, 0 值被省略")
	} else if *page.PageSize != 10 {
		t.Errorf("pageSize=%d, want 10", *page.PageSize)
	}
	if page.Total != 11 || page.TotalPages != 2 {
		t.Errorf("分页元数据错误: total=%d totalPages=%d, want 11/2", page.Total, page.TotalPages)
	}
}

