func TestGetCaseDetail_SoftDeleted_MustReturnEnvelope404(t *testing.T) {
	db := setupCaseDetailTestDB(t)
	if err := db.Exec("DELETE FROM functional_case WHERE id = ?", "case-soft-1").Error; err != nil {
		t.Fatalf("clean fixture: %v", err)
	}
	seed := model.FunctionalCase{
		ID:        "case-soft-1",
		ProjectID: "p1",
		Name:      "已删除用例",
		Deleted:   model.BitBool(true),
		CreatedAt: 1,
		UpdatedAt: 1,
	}
	if err := db.Create(&seed).Error; err != nil {
		t.Fatalf("seed: %v", err)
	}

	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.GET("/functional/case/detail", NewTestCaseHandler().GetCaseDetail)
	r.POST("/functional/case/detail", NewTestCaseHandler().GetCaseDetail)

	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/functional/case/detail?id=case-soft-1", nil))
	var envelope struct {
		Code    int             `json:"code"`
		Data    json.RawMessage `json:"data"`
		Message string          `json:"message"`
	}
	if err := json.Unmarshal(w.Body.Bytes(), &envelope); err != nil {
		t.Fatalf("envelope unmarshal: %v body=%s", err, w.Body.String())
	}
	if w.Code != http.StatusOK {
		t.Errorf("响应信封约定: http=%d, want 200 (业务错误码放在 body.code)", w.Code)
	}
	if envelope.Code != 404 {
		t.Errorf("软删用例必须不可见: code=%d message=%s, want 404", envelope.Code, envelope.Message)
	}
	if got := string(bytes.TrimSpace(envelope.Data)); got != "null" {
		t.Errorf("失败响应 data=%s, want null", got)
	}

	w2 := httptest.NewRecorder()
	req2 := httptest.NewRequest(http.MethodPost, "/functional/case/detail", bytes.NewReader([]byte(`{}`)))
	req2.Header.Set("Content-Type", "application/json")
	r.ServeHTTP(w2, req2)
	var envelope2 struct {
