		Message string `json:"message"`
	}
	if err := json.Unmarshal(w2.Body.Bytes(), &envelope2); err != nil {
		t.Fatalf("envelope2 unmarshal: %v body=%s", err, w2.Body.String())
	}
	if envelope2.Code == 404 {
		t.Errorf("缺失 id 被误报为资源不存在: code=404 message=%s (ShouldBindJSON 错误被 _ = 忽略后以空串查询)", envelope2.Message)
	}
