func TestGetModuleTree_EmptyAndLeafChildren_MustBeArrays(t *testing.T) {
	db := setupModuleTreeTestDB(t)
	if err := db.Exec("DELETE FROM functional_case_module WHERE project_id = ?", "p-tree").Error; err != nil {
		t.Fatalf("clean fixture: %v", err)
	}
	leaf := model.FunctionalCaseModule{ID: "mod-leaf", ProjectID: "p-tree", Name: "叶子模块", ParentID: "NONE", CreatedAt: 1, UpdatedAt: 1}
	if err := db.Create(&leaf).Error; err != nil {
		t.Fatalf("seed: %v", err)
	}

	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.GET("/functional/case/module/tree", NewTestCaseHandler().GetModuleTree)

	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/functional/case/module/tree?projectId=p-tree", nil))

	var envelope struct {
		Code int             `json:"code"`
		Data json.RawMessage `json:"data"`
	}
	if err := json.Unmarshal(w.Body.Bytes(), &envelope); err != nil {
		t.Fatalf("envelope unmarshal: %v body=%s", err, w.Body.String())
	}
	if envelope.Code != 200 {
		t.Fatalf("code=%d, want 200", envelope.Code)
	}
	if got := string(bytes.TrimSpace(envelope.Data)); got == "null" {
		t.Fatalf("data=null, want [] (var rootNodes []*model.FunctionalCaseModule 为 nil)")
	}

	var nodes []map[string]json.RawMessage
	if err := json.Unmarshal(envelope.Data, &nodes); err != nil {
		t.Fatalf("data 不是数组: %v data=%s", err, string(envelope.Data))
	}
	if len(nodes) != 1 {
		t.Fatalf("root 节点数=%d, want 1", len(nodes))
	}
	children, ok := nodes[0]["children"]
	if !ok {
		t.Errorf("叶子模块缺少 children 键: tag 为 children,omitempty, 空切片被整体省略导致前端 node.children.map 崩溃")
	} else if string(bytes.TrimSpace(children)) != "[]" {
		t.Errorf("children=%s, want []", string(bytes.TrimSpace(children)))
	}

	w2 := httptest.NewRecorder()
	r.ServeHTTP(w2, httptest.NewRequest(http.MethodGet, "/functional/case/module/tree?projectId=p-no-module", nil))
	if !bytes.Contains(w2.Body.Bytes(), []byte(`"data":[]`)) {
		t.Errorf("空项目模块树必须为 []: body=%s", w2.Body.String())
	}
}

