func TestDeleteModule_ThreeLevel_MustNotLeaveOrphan(t *testing.T) {
	db := setupModuleDeleteTestDB(t)
	if err := db.Exec("DELETE FROM functional_case_module WHERE project_id = ?", "p-del").Error; err != nil {
		t.Fatalf("clean fixture: %v", err)
	}
	mods := []model.FunctionalCaseModule{
		{ID: "mod-a", ProjectID: "p-del", Name: "A", ParentID: "NONE", CreatedAt: 1, UpdatedAt: 1},
		{ID: "mod-b", ProjectID: "p-del", Name: "B", ParentID: "mod-a", CreatedAt: 2, UpdatedAt: 2},
		{ID: "mod-c", ProjectID: "p-del", Name: "C", ParentID: "mod-b", CreatedAt: 3, UpdatedAt: 3},
	}
	for i := range mods {
		if err := db.Create(&mods[i]).Error; err != nil {
			t.Fatalf("seed %s: %v", mods[i].ID, err)
		}
	}

	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.POST("/functional/case/module/delete", NewTestCaseHandler().DeleteModule)
	r.GET("/functional/case/module/tree", NewTestCaseHandler().GetModuleTree)

	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodPost, "/functional/case/module/delete", bytes.NewReader([]byte(`{"id":"mod-b"}`)))
	req.Header.Set("Content-Type", "application/json")
	r.ServeHTTP(w, req)

	var orphan int64
	if err := db.Model(&model.FunctionalCaseModule{}).Where("id = ?", "mod-c").Count(&orphan).Error; err != nil {
		t.Fatalf("count mod-c: %v", err)
	}
	if orphan != 0 {
		t.Errorf("删除 mod-b 后 mod-c 仍存在 %d 行: Where(id = ? OR parent_id = ?) 只删一层, 孙节点 parent_id 悬空", orphan)
	}

	var dangling int64
	if err := db.Raw("SELECT COUNT(*) FROM functional_case_module m LEFT JOIN functional_case_module p ON m.parent_id = p.id WHERE m.parent_id NOT IN ('NONE','root','') AND p.id IS NULL").Scan(&dangling).Error; err != nil {
		t.Fatalf("dangling query: %v", err)
	}
	if dangling != 0 {
		t.Errorf("存在 %d 个 parent_id 悬空的孤儿模块, want 0", dangling)
	}

	w2 := httptest.NewRecorder()
	r.ServeHTTP(w2, httptest.NewRequest(http.MethodGet, "/functional/case/module/tree?projectId=p-del", nil))
	if bytes.Contains(w2.Body.Bytes(), []byte("mod-c")) {
		t.Errorf("孤儿模块 mod-c 被提升为根节点出现在模块树: body=%s", w2.Body.String())
	}
}

