		Message string `json:"message"`
	}
	if err := json.Unmarshal(w.Body.Bytes(), &envelope); err != nil {
		t.Fatalf("envelope unmarshal: %v body=%s", err, w.Body.String())
	}
	if envelope.Code != 100401 {
		t.Errorf("匿名创建项目未被拒绝: http=%d code=%d message=%s (AuthMiddleware 无 token 时不设置 userId, handler 回落 uid=admin)", w.Code, envelope.Code, envelope.Message)
	}

	var count int64
	if err := db.Model(&model.Project{}).Where("name = ?", "未鉴权项目").Count(&count).Error; err != nil {
		t.Fatalf("count: %v", err)
	}
	if count != 0 {
		t.Errorf("匿名请求写入 project 表 %d 行, want 0", count)
	}
}

